-- Owner-provided product artwork, 2026-10-26. Image-only update, no commercial changes.
UPDATE products SET settings=replace(settings::text, '/assets/enbishan-menu/owner-review/mojito-grape.jpeg', '/assets/enbishan-menu/owner-20261026/mojito-grape.jpeg')::jsonb WHERE brand_id='enbishan' AND (settings->>'image_url'='/assets/enbishan-menu/owner-review/mojito-grape.jpeg' OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(settings->'variant_images','[]'::jsonb)) v WHERE v->>'image_url'='/assets/enbishan-menu/owner-review/mojito-grape.jpeg'));
